<div class="admin-title"><div><span class="eyebrow">ONE SECRET. ONE ORDER.</span><h1><?= e($title) ?></h1><p><?= t('Code inventory is encrypted. A successful purchase atomically assigns one unused code to one order.') ?></p></div><a class="btn secondary" href="<?= e(au('edit_content',['kind'=>'product'])) ?>"><?= t('Create a product') ?></a></div><div class="two-column"><section class="panel"><h2><?= t('Import delivery codes') ?></h2><?= form_start('admin_stock') ?><?php $products=[];foreach($a->db->all("SELECT id,title FROM cy_contents WHERE kind='product' AND product_type='code' ORDER BY id DESC") as $p) {$products[$p['id']]=$p['title'];}select_field('content_id','Code-delivery product',$products);$variants=[0=>tr('No variant')];foreach($a->db->all('SELECT v.id,v.name,v.content_id FROM cy_variants v JOIN cy_contents c ON c.id=v.content_id WHERE c.product_type=? ORDER BY v.content_id,v.id',['code']) as $v){$variants[$v['id']]='#'.$v['content_id'].' / '.$v['name'];}select_field('variant_id','Product variant (must match product)',$variants);field('codes','One delivery code per line','','textarea',['required'=>'required','rows'=>'14']);button('Import encrypted inventory','full','lock'); ?><p class="hint"><?= t('Up to 500 codes per import. Do not import duplicate sold codes. Set the product delivery type to code before importing.') ?></p></form></section><section class="panel"><h2><?= t('Inventory overview') ?></h2><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Product') ?></th><th><?= t('Unused') ?></th><th><?= t('Assigned') ?></th></tr></thead><tbody><?php foreach ($products as $id=>$name): ?><tr><td><a href="<?= e(au('edit_content',['id'=>$id])) ?>"><?= e($name) ?></a></td><td><?= (int)$a->db->value('SELECT COUNT(*) FROM cy_stock_codes WHERE content_id=? AND order_id IS NULL',[(int)$id]) ?></td><td><?= (int)$a->db->value('SELECT COUNT(*) FROM cy_stock_codes WHERE content_id=? AND order_id IS NOT NULL',[(int)$id]) ?></td></tr><?php endforeach ?></tbody></table></div><div class="alert info"><?= t('Refunding a delivered code does not return it to inventory. A secret that has been revealed cannot be made secret again.') ?></div></section></div>
